@extends('admin.layout') @section('title','Edit landing page') @section('content')<p><a href="/admin/landing-pages">← Back to landing pages</a></p><h1>{{ $page->exists?'Edit':'Create' }} landing page</h1>@if($errors->any())<div class="errors">@foreach($errors->all() as $error)<p>{{ $error }}</p>@endforeach</div>@endif<div class="panel"><form method="post" action="{{ $page->exists?'/admin/landing-pages/'.$page->id:'/admin/landing-pages' }}">@csrf @if($page->exists)@method('PUT')@endif<div class="form-grid">@foreach(['city'=>'City','slug'=>'URL slug','headline'=>'Headline','subheadline'=>'Subheadline','intro'=>'Intro','meta_title'=>'SEO title','meta_description'=>'SEO description','faq_text'=>'FAQs','callout_note'=>'Call-out note'] as $field=>$label)<label class="field {{ in_array($field,['intro','faq_text','subheadline'])?'full':'' }}">{{ $label }}@if(in_array($field,['intro','subheadline','faq_text','meta_description']))<textarea name="{{ $field }}" rows="{{ $field==='intro'?5:3 }}">{{ old($field,$page->$field) }}</textarea>@else<input name="{{ $field }}" value="{{ old($field,$page->$field) }}">@endif</label>@endforeach<div class="full"><label><input type="checkbox" name="is_active" value="1" {{ old('is_active',$page->exists?$page->is_active:true)?'checked':'' }}> Page live</label><p><label><input type="checkbox" name="indexable" value="1" {{ old('indexable',$page->indexable)?'checked':'' }}> Allow search indexing (review unique content first)</label></p></div></div><button class="btn" type="submit">Save landing page</button></form></div>@endsection